<?php if($resource['deleted_at']): ?><p class="audience-notice">This form is archived. Public collection has stopped and existing results are kept.</p><?php endif; ?>
<?php if($resource['kind']==='survey'): ?><h2>Review your results</h2><p><?= $h($resource['name']) ?> has collected <?= number_format($totalResponses) ?> <?= $answerFilter!==''?'matching ':'' ?>responses</p><strong><?= $answerFilter!==''?'Browsing selected responses':'Browsing all responses' ?></strong><nav class="collection-report-tabs" aria-label="Survey questions"><a class="audience-button<?= $questionFilter===''?' selected':'' ?>" href="<?= $h($url(['view'=>'collection-report','id'=>$id,'start'=>$reportStart,'end'=>$reportEnd])) ?>">All responses</a><?php foreach($reportDocuments as$rev=>$published)foreach($published['document']['questions']as$i=>$q): ?><a class="audience-button<?= $questionFilter===$q['id']&&$revisionFilter===$rev?' selected':'' ?>" href="<?= $h($url(['view'=>'collection-report','id'=>$id,'start'=>$reportStart,'end'=>$reportEnd,'revision'=>$rev,'question'=>$q['id']])) ?>">Question <?= $i+1 ?>: <?= $h($q['label']) ?></a><?php endforeach; ?></nav><?php endif; ?>
<form method="get" class="collection-filters collection-report-filters"><?php audienceInputs(['view'=>'collection-report','id'=>$id,'revision'=>$revisionFilter,'question'=>$questionFilter,'answer'=>$answerFilter]); ?><label>Start date<input type="date" name="start" value="<?= $h($reportStart) ?>"></label><label>End date<input type="date" name="end" value="<?= $h($reportEnd) ?>"></label><button>Apply</button><?php if(!$resource['deleted_at']): ?><a href="<?= $h($url(['view'=>'form','id'=>$id])) ?>">Go to <?= $resource['kind']==='survey'?'survey':'form' ?> details</a><?php else: ?><a href="<?= $h($url(['view'=>match($resource['kind']){'survey'=>'surveys','landing'=>'landing-pages','preferences'=>'preferences',default=>'forms'},'trash'=>'1'])) ?>">Back to Archived</a><?php endif; ?></form>
<div class="collection-metrics"><article><h2><?= number_format($visits) ?></h2><p>Daily unique visits</p></article><article><h2><?= number_format($totalResponses) ?></h2><p><?= $resource['kind']==='survey'?'Responses':'Submissions' ?></p></article><?php if(!in_array($resource['kind'],['survey','preferences'],true)): ?><article><h2><?= number_format((int)$conversions['subscribers']) ?></h2><p>Subscribers</p></article><article><h2><?= number_format((int)$conversions['confirmed']) ?></h2><p>Confirmed double opt-ins</p></article><article><h2><?= $visits?round((int)$conversions['subscribers']/$visits*100,1).'%':'—' ?></h2><p>Conversion rate</p></article><?php else: ?><article><h2><?= $visits?round($totalResponses/$visits*100,1).'%':'—' ?></h2><p>Responses per visit</p></article><?php endif; ?></div><p class="audience-help">Visits count a browser once per day. Subscribers count distinct connections that subscribed through this form during the selected dates; confirmation is counted when the delivered link is completed. Existing subscribers and unconfirmed requests do not add conversions. Browser privacy settings can affect visit counts.</p>
<?php if(!$totalResponses): ?><section class="collection-empty"><h2>No responses yet</h2><p>Publish and share the form to start collecting responses.</p></section><?php endif; ?>
<?php if($resource['kind']==='survey'): ?>
<?php foreach($reportDocuments as$rev=>$published): if(empty($revisionTotals[$rev]))continue; ?><p class="audience-help">Published revision <?= $rev ?> · <?= $h($published['at']) ?> UTC</p><?php foreach($published['document']['questions']as$q): if($questionFilter!==''&&($revisionFilter!==$rev||$questionFilter!==$q['id']))continue; ?><section class="collection-chart"><div class="collection-list-head"><h2><?= $h($q['label']) ?></h2><?php if($canManage): ?><a class="audience-button" href="<?= $h($url($reportQuery+['chart'=>$rev.':'.$q['id']])) ?>">Download chart</a><?php endif; ?></div><?php if(in_array($q['type'],['radio','checkboxes','range','dropdown'],true)): ?><?php foreach($report[$rev][$q['id']]??[]as$answer=>$n): ?><div><a href="<?= $h($url(array_replace($reportQuery,['revision'=>$rev,'question'=>$q['id'],'answer'=>$answer]))) ?>"><?= $h($answer) ?></a><meter min="0" max="<?= max(1,$questionTotals[$rev][$q['id']]??0) ?>" value="<?= $n ?>"><?= $n ?></meter><strong><?= $n ?> <small>(<?= round(100*$n/max(1,$questionTotals[$rev][$q['id']]??0),1) ?>%)</small></strong></div><?php endforeach; ?><?php else: ?><p class="audience-help">Read individual answers in Responses below.</p><?php endif; ?></section><?php endforeach; endforeach; ?>
<?php endif; ?>
<h2>Responses</h2><div class="audience-table-scroll"><table data-mm-paginated-table class="data-table collection-table"><thead><tr><th>Response</th><th>Submitted (UTC)</th><th>Variation</th><th>Connection</th><th>Answers</th></tr></thead><tbody><?php foreach($responses as$r): ?><tr><td><?= (int)$r['id'] ?></td><td><?= $h($r['created_at']) ?></td><td><?= $h($r['variant_key']) ?></td><td><div class="collection-response-connection"><?php if($r['contact_id']): ?><a href="<?= $h($url(['view'=>'contact','id'=>$r['contact_id']])) ?>">Verified connection</a><?php if($canManage): ?><form method="post" class="collection-response-tags"><?= $csrf ?><?php audienceInputs(['action'=>'collection_tag','id'=>$id,'response'=>$r['id']]); ?><label>Tag<select name="tag_id" required><option value="">Choose</option><?php foreach($tags as$t): ?><option value="<?= (int)$t['id'] ?>"><?= $h($t['name']) ?></option><?php endforeach; ?></select></label><button>Apply tag</button></form><?php endif; ?><?php else: ?>Anonymous<?php endif; ?></div></td><td><details><summary>View response</summary><dl><?php foreach($r['answers']as$key=>$value): ?><dt><?= $h($key) ?></dt><dd><?= $h(is_array($value)?implode(', ',array_filter($value,'is_scalar')):(is_bool($value)?($value?'Yes':'No'):$value)) ?></dd><?php endforeach; ?></dl></details></td></tr><?php endforeach; ?></tbody></table></div>
<?php audiencePagination(['total'=>$totalResponses,'page'=>$responsePage,'size'=>$responseSize,'label'=>'Response pages','params'=>$reportQuery,'url'=>$url]); ?>
